mapper.select:
SELECT  FROM provider_connection
WHERE user_id = #{userId}
ORDER BY provider

SELECT  FROM provider_connection
WHERE user_id = #{userId} AND provider = #{provider}
FOR UPDATE

SELECT  FROM provider_connection
WHERE user_id = #{userId} AND provider = #{provider}
FOR SHARE

mapper.insert:
INSERT INTO provider_connection (
  user_id, provider, status, provider_account_email, provider_account_id,
  granted_scopes, credential_ref, credential_generation, access_token_expires_at,
  capture_reconcile_required, capture_reconcile_after_workspace_id, error_code
) VALUES (
  #{userId}, #{provider}, #{status}, #{providerAccountEmail}, #{providerAccountId},
  #{grantedScopes}, #{credentialRef}, #{credentialGeneration}, #{accessTokenExpiresAt},
  #{captureReconcileRequired}, #{captureReconcileAfterWorkspaceId}, #{errorCode}
)

mapper.update:
UPDATE provider_connection
SET disconnect_attempt_at = UTC_TIMESTAMP(6)
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND status = 'revoking'
  AND (
    disconnect_attempt_at IS NULL
    OR disconnect_attempt_at < DATE_SUB(UTC_TIMESTAMP(6), INTERVAL 10 MINUTE)
  )

UPDATE provider_connection
SET disconnect_attempt_at = UTC_TIMESTAMP(6)
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND status IN ('disconnecting', 'purge_failed')
  AND (
    disconnect_attempt_at IS NULL
    OR disconnect_attempt_at < DATE_SUB(UTC_TIMESTAMP(6), INTERVAL 10 MINUTE)
  )

mapper.select:
SELECT EXISTS(
  SELECT 1
  FROM provider_connection
  WHERE id = #{id}
    AND credential_generation = #{generation}
    AND status IN ('disconnecting', 'purge_failed')
)

mapper.update:
UPDATE provider_connection
SET status = 'purge_failed',
    error_code = #{errorCode},
    disconnect_attempt_at = UTC_TIMESTAMP(6)
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND capture_reconcile_lease_owner = #{owner}

UPDATE provider_connection
SET refresh_lease_owner = #{owner},
    refresh_lease_until = #{until}
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND status = 'connected'
  AND (refresh_lease_until IS NULL OR refresh_lease_until < #{now})

UPDATE provider_connection
SET credential_ref = #{credentialRef},
    access_token_expires_at = #{expiresAt},
    refresh_lease_owner = NULL,
    refresh_lease_until = NULL,
    error_code = NULL
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND refresh_lease_owner = #{owner}

UPDATE provider_connection
SET status = 'error',
    error_code = #{errorCode},
    refresh_lease_owner = NULL,
    refresh_lease_until = NULL
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND refresh_lease_owner = #{owner}

UPDATE provider_connection
SET error_code = #{errorCode},
    refresh_lease_owner = NULL,
    refresh_lease_until = NULL
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND status = 'connected'
  AND refresh_lease_owner = #{owner}

UPDATE provider_connection
SET capture_reconcile_lease_owner = #{owner},
    capture_reconcile_lease_until = #{until}
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND capture_reconcile_required = TRUE
  AND (
    capture_reconcile_next_attempt_at IS NULL
    OR capture_reconcile_next_attempt_at <= #{now}
  )
  AND (
    capture_reconcile_lease_until IS NULL
    OR capture_reconcile_lease_until < #{now}
  )

UPDATE provider_connection
SET capture_reconcile_lease_until = #{until}
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND capture_reconcile_required = TRUE
  AND capture_reconcile_lease_owner = #{owner}

UPDATE provider_connection
SET capture_reconcile_lease_owner = NULL,
    capture_reconcile_lease_until = NULL,
    capture_reconcile_next_attempt_at =
      DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 1 MINUTE),
    capture_reconcile_failures = capture_reconcile_failures + 1
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND capture_reconcile_required = TRUE
  AND capture_reconcile_lease_owner = #{owner}

mapper.delete:
DELETE FROM provider_connection
WHERE id = #{id}
  AND credential_generation = #{generation}
  AND status IN ('disconnecting', 'purge_failed')
